function ewsifyConfig(config, includeExchangeAddon = true) {
  // At present, account setup code uses the "exchange" incoming server type
  // to store a configuration suitable for OWL. In order to avoid breaking
  // OWL (which uses some config fields in an idiosyncratic manner), we use
  // the "ews" type. So that both are presented in the UI, we duplicate the
  // "exchange" config and adjust its fields as needed.
  const exchangeIncoming = getIncomingExchangeConfig(config);

  if (!exchangeIncoming) {
    return;
  }

  const ewsIncoming = structuredClone(exchangeIncoming);
  ewsIncoming.type = "ews";

/**
 * True if the incoming and outgoing server authentication methods do not
 * require password entry.
 *
 * @returns {boolean}
 */
usesPasswordlessAuthentication() {
  return (
    this.authDoesNotRequirePassword(this.incoming.auth) &&
    (this.configureOutgoingFromIncoming() ||
      this.authDoesNotRequirePassword(this.outgoing.auth))
  );
},

/**
 * True if a server authentication method does not require password entry.
 *
 * @param {Ci.nsMsgAuthMethod} authMethod - Authentication method.
 * @returns {boolean}
 */
authDoesNotRequirePassword(authMethod) {
  return [
    Ci.nsMsgAuthMethod.none,
    Ci.nsMsgAuthMethod.GSSAPI,
    Ci.nsMsgAuthMethod.OAuth2,
  ].includes(authMethod);
},
